% Reconstruction of spec-mission-lifecycle.tex's first decoupled
% demonstration document (its "A decoupled demonstration" subsection):
% MissionU (structural bounds only, no abandon invariant) + Init +
% Delegate + Idle + AbandonFailOpen, per the verbatim blocks and prose
% at spec-mission-lifecycle.tex:1056-1105 and 979-996.
\documentclass{article}
\usepackage{fuzz}
\begin{document}

\begin{zed}
Status ::= stOpen | stClosed | stFailed | stEscalated | stAbandoned
\end{zed}

\begin{zed}
ZBOOL ::= ztrue | zfalse
\end{zed}

\begin{axdef}
maxRounds : \nat
\where
maxRounds = 3
\end{axdef}

\begin{axdef}
maxDelegations : \nat
\where
maxDelegations = 2
\end{axdef}

\begin{schema}{MissionU}
status : Status \\
budgetRounds : \nat \\
blockingDelegationCount : \nat \\
resultRounds : \finset \nat \\
repoRootSet : ZBOOL
\where
budgetRounds \in 1 \upto maxRounds \\
blockingDelegationCount \leq maxDelegations \\
resultRounds \subseteq 1 \upto budgetRounds
\end{schema}

\begin{schema}{Init}
MissionU'
\where
status' = stOpen \\
blockingDelegationCount' = 0 \\
resultRounds' = \emptyset
\end{schema}

\begin{schema}{Delegate}
\Delta MissionU
\where
status = stOpen \\
blockingDelegationCount < maxDelegations \\
status' = status \\
budgetRounds' = budgetRounds \\
blockingDelegationCount' = blockingDelegationCount + 1 \\
resultRounds' = resultRounds \\
repoRootSet' = repoRootSet
\end{schema}

\begin{schema}{AbandonFailOpen}
\Delta MissionU
\where
status = stOpen \\
(repoRootSet = ztrue \implies
  (blockingDelegationCount = 0 \land resultRounds = \emptyset)) \\
status' = stAbandoned \\
budgetRounds' = budgetRounds \\
blockingDelegationCount' = blockingDelegationCount \\
resultRounds' = resultRounds \\
repoRootSet' = repoRootSet
\end{schema}

\begin{schema}{Idle}
\Xi MissionU
\where
\lnot (status = stAbandoned \land
  (blockingDelegationCount \neq 0 \lor resultRounds \neq \emptyset))
\end{schema}

\end{document}
